#include <bits/stdc++.h>
using namespace std;

char s[101];
int dx[] = {0, 0, 0, 1, -1};
int dy[] = {0, 1, -1, 0, 0};

int main() {
    scanf("%s", s);
    int n = strlen(s);
    int x = 0, y = 0;
    set<pair<int, int>> vis;
    vis.insert({0, 0});

    bool ok = true;
    for (int i = 0; i < n && ok; ++i) {
        int px = x, py = y;

        if (s[i] == 'R')
            ++y;
        else if (s[i] == 'L')
            --y;
        else if (s[i] == 'U')
            --x;
        else if (s[i] == 'D')
            ++x;

        for (int j = 0; j < 5 && ok; ++j) {
            int tx = x + dx[j];
            int ty = y + dy[j];

            if ((tx != px || ty != py) && vis.count({tx, ty}))
                ok = false;
        }

        vis.insert({x, y});
    }

    puts(ok ? "OK" : "BUG");
    return 0;
}

